import numpy as np
X=np.array([.5,.8,1.1,1.4,2.0,2.2,2.8,3.2]); y=np.array([0,0,0,1,0,1,1,1])
def gini(a):
    if len(a)==0:return 0
    p=np.bincount(a,minlength=2)/len(a); return 1-np.sum(p*p)
parent=gini(y); best=None
for s in (X[:-1]+X[1:])/2:
    left=X<=s; weighted=(left.mean()*gini(y[left])+(~left).mean()*gini(y[~left])); gain=parent-weighted
    if best is None or gain>best[0]: best=(gain,s,y[left].mean(),y[~left].mean())
print(f"best split x <= {best[1]:.2f}; Gini gain={best[0]:.3f}; leaf positive rates={best[2]:.2f}, {best[3]:.2f}")
